var stringssplitTests = []testCase{
	{
		Name: "stringssplit.0",
		In: `package main

import (
	"bytes"
	"strings"
)

func f() {
	bytes.Split(a, b, c)
	bytes.Split(a, b, -1)
	bytes.SplitAfter(a, b, c)
	bytes.SplitAfter(a, b, -1)
