	strings.SplitAfter(a, b, c)
	strings.SplitAfter(a, b, -1)
}
`,
		Out: `package main

import (
	"bytes"
	"strings"
)

func f() {
	bytes.SplitN(a, b, c)
	bytes.Split(a, b)
	bytes.SplitAfterN(a, b, c)
	bytes.SplitAfter(a, b)
	strings.SplitN(a, b, c)
	strings.Split(a, b)
	strings.SplitAfterN(a, b, c)
	strings.SplitAfter(a, b)
}
`,
	},
}

